(async () => {
  try {
    const tc = window.TuquetCrawler;
    const startTime = Date.now();
    const rawHtmlLength = document.documentElement.outerHTML.length;
    const crawl = await tc.crawlDocument(document, {
      autoDismissModals: true,
      autoScroll: false,
      extractMetadata: true,
      extractMainContent: true,
      toMarkdown: true
    });
    const markdown = crawl.markdown || '';
    const tokenSavings = tc.estimateTokenSavings(document.documentElement.outerHTML, markdown);
    const priceMatch = document.body.innerText.match(/£[0-9.]+/);
    const stockMatch = document.body.innerText.match(/In stock \([0-9]+ available\)/);
    automaNextBlock({
      success: true,
      domain: 'books.toscrape.com',
      url: window.location.href,
      pageType: crawl.pageType,
      title: crawl.metadata?.title || document.title,
      price: priceMatch ? priceMatch[0] : null,
      stock: stockMatch ? stockMatch[0] : null,
      articleScore: crawl.article?.confidenceScore,
      rawLength: rawHtmlLength,
      markdownLength: markdown.length,
      tokenSavings: tokenSavings,
      markdownSample: markdown.slice(0, 800),
      executionMs: Date.now() - startTime
    });
  } catch (err) {
    automaNextBlock({ $error: true, message: err.message });
  }
})();
